--[=[
    @interface INZConnection
    连接管理接口，用于处理事件连接和生命周期
]=]
export type INZConnection = {
    --[=[
        创建新的连接实例
        @param eventOrEvents RBXScriptSignal | {RBXScriptSignal} 事件或事件数组
        @param func function 回调函数
        @param inst boolean? 是否立即执行
        @param ... any 立即执行的参数
        @return INZConnection
    ]=]
    new: (eventOrEvents: any | {any}, func: (...any) -> (), inst: boolean?, ...any) -> INZConnection,

    --[=[
        创建一次性连接实例
        @param eventOrEvents RBXScriptSignal | {RBXScriptSignal} 事件或事件数组
        @param func function 回调函数
        @return INZConnection
    ]=]
    once: (eventOrEvents: any | {any}, func: (...any) -> ()) -> INZConnection,

    --[=[
        命名连接实例
        @param name string 连接名称
        @return INZConnection
    ]=]
    Named: (self: INZConnection, name: string) -> INZConnection,

    --[=[
        设置期望值
        @param ... any 期望值列表
        @return INZConnection
    ]=]
    Expect: (self: INZConnection, ...any) -> INZConnection,

    --[=[
        设置错误捕获处理
        @param func function 错误处理函数
        @return INZConnection
    ]=]
    Catch: (self: INZConnection, func: (...any) -> ()) -> INZConnection,

    --[=[
        设置最终处理
        @param func function 最终处理函数
        @return INZConnection
    ]=]
    Finally: (self: INZConnection, func: (...any) -> ()) -> INZConnection,

    --[=[
        设置成功处理
        @param func function 成功处理函数
        @return INZConnection
    ]=]
    Then: (self: INZConnection, func: (...any) -> ()) -> INZConnection,

    --[=[
        断开连接
    ]=]
    Disconnect: (self: INZConnection) -> (),

    --[=[
        设置启用状态
        @param enabled boolean? 是否启用，默认为true
    ]=]
    SetEnabled: (self: INZConnection, enabled: boolean?) -> (),

    --[=[
        禁用连接
    ]=]
    Disable: (self: INZConnection) -> (),

    --[=[
        启用连接
    ]=]
    Enable: (self: INZConnection) -> (),

    --[=[
        销毁连接
    ]=]
    Destroy: (self: INZConnection) -> (),

    --[=[
        设置源连接启用状态
        @param enabled boolean 是否启用
        @static
    ]=]
    SetSourceConnectionsEnabled: (enabled: boolean) -> (),

    --[=[
        获取连接启用状态
        @param connection INZConnection 连接实例
        @return boolean
        @static
    ]=]
    GetEnable: (connection: INZConnection) -> boolean,

    --[=[
        事件源
        @prop Source any
        @within INZConnection
    ]=]
    Source: any,

    --[=[
        事件对象
        @prop Event RBXScriptSignal | {RBXScriptSignal}
        @within INZConnection
    ]=]
    Event: any | {any},

    --[=[
        目标函数
        @prop Target function
        @within INZConnection
    ]=]
    Target: (...any) -> (),

    --[=[
        连接名称
        @prop Name string?
        @within INZConnection
    ]=]
    Name: string?,
}

return {} 